send-request.set-body:
@{
                    int inTok  = 0; int outTok = 0;
                    int.TryParse(context.Variables.GetValueOrDefault("content-input-tokens",  "0"), out inTok);
                    int.TryParse(context.Variables.GetValueOrDefault("content-output-tokens", "0"), out outTok);

                    var arr = new Newtonsoft.Json.Linq.JArray {
                        new Newtonsoft.Json.Linq.JObject {
                            ["TimeGenerated"]      = System.DateTime.UtcNow.ToString("o"),
                            ["CorrelationId"]      = context.Variables.GetValueOrDefault("content-correlation-id", ""),
                            ["RequestId"]          = context.RequestId,
                            ["Direction"]          = context.Variables.GetValueOrDefault("content-direction", ""),
                            ["Backend"]            = context.Variables.GetValueOrDefault("content-backend", ""),
                            ["Model"]              = context.Variables.GetValueOrDefault("content-model", ""),
                            ["ApiName"]            = context.Api == null ? "" : context.Api.Name,
                            ["OperationName"]      = context.Operation == null ? "" : context.Operation.Name,
                            ["User"]               = context.Variables.GetValueOrDefault("content-user", "anonymous"),
                            ["SubscriptionId"]     = context.Subscription == null ? "" : context.Subscription.Id,
                            ["InputTokens"]        = inTok,
                            ["OutputTokens"]       = outTok,
                            ["PurviewBlocked"]     = context.Variables.GetValueOrDefault("content-purview-blocked", "false") == "true",
                            ["PurviewBlockReason"] = context.Variables.GetValueOrDefault("content-purview-block-reason", "none"),
                            ["Content"]            = context.Variables.GetValueOrDefault("content-text", "")
                        }
                    };
                    return arr.ToString();
                }
